B.abm=new A.n([B.G,"Forge unavailable. Sign in and retry later.",B.l,"Officina non disponibile. Accedi e riprova pi\xf9 tardi.",B.k,"Forja no disponible. Inicia sesi\xf3n e int\xe9ntalo m\xe1s tarde.",B.i,"\u935b\u51b6\u5834\u3092\u5229\u7528\u3067\u304d\u307e\u305b\u3093\u3002\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u518d\u8a66\u884c\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub300\uc7a5\uac04\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. \ub85c\uadf8\uc778 \ud6c4 \ub2e4\uc2dc \uc2dc\ub3c4\ud558\uc138\uc694.",B.f,"\u953b\u9020\u6682\u4e0d\u53ef\u7528\uff0c\u8bf7\u767b\u5f55\u540e\u91cd\u8bd5\u3002",B.j,"Schmiede nicht verf\xfcgbar. Anmelden und sp\xe4ter erneut versuchen."],t.N)
B.ab0=new A.n([B.G,"Progress changed. Refresh before another attempt.",B.l,"Progressi cambiati. Aggiorna prima di riprovare.",B.k,"El progreso cambi\xf3. Actualiza antes de reintentar.",B.i,"\u9032\u884c\u72b6\u6cc1\u304c\u5909\u308f\u308a\u307e\u3057\u305f\u3002\u66f4\u65b0\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uc9c4\ud589 \uc0c1\ud669\uc774 \ubcc0\uacbd\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc0c8\ub85c\uace0\uce68\ud558\uc138\uc694.",B.f,"\u8fdb\u5ea6\u5df2\u53d8\u66f4\uff0c\u8bf7\u5237\u65b0\u540e\u91cd\u8bd5\u3002",B.j,"Fortschritt ge\xe4ndert. Vor erneutem Versuch aktualisieren."],t.N)
B.abw=new A.n([B.G,"Resolve your duplicate card first.",B.l,"Risolvi prima la carta duplicata.",B.k,"Resuelve primero la carta duplicada.",B.i,"\u5148\u306b\u91cd\u8907\u30ab\u30fc\u30c9\u3092\u51e6\u7406\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\uba3c\uc800 \uc911\ubcf5 \uce74\ub4dc\ub97c \ucc98\ub9ac\ud558\uc138\uc694.",B.f,"\u8bf7\u5148\u5904\u7406\u91cd\u590d\u5361\u724c\u3002",B.j,"Zuerst die doppelte Karte bearbeiten."],t.N)
B.ab2=new A.n([B.G,"Account restricted",B.l,"Account bloccato",B.k,"Cuenta restringida",B.i,"\u30a2\u30ab\u30a6\u30f3\u30c8\u5236\u9650\u4e2d",B.h,"\uacc4\uc815 \uc81c\ud55c\ub428",B.f,"\u8d26\u6237\u53d7\u9650",B.j,"Konto gesperrt"],t.N)
B.abt=new A.n([B.G,"Result not received. Retry the same attempt; it will not charge twice.",B.l,"Esito non ricevuto. Riprova lo stesso tentativo: nessun doppio consumo.",B.k,"Resultado no recibido. Reintenta: no se cobrar\xe1 dos veces.",B.i,"\u7d50\u679c\u3092\u53d7\u4fe1\u3067\u304d\u307e\u305b\u3093\u3002\u540c\u3058\u8a66\u884c\u3092\u518d\u9001\u3057\u3066\u3082\u4e8c\u91cd\u6d88\u8cbb\u3055\u308c\u307e\u305b\u3093\u3002",B.h,"\uacb0\uacfc\ub97c \ubc1b\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4. \uc7ac\uc2dc\ub3c4\ud574\ub3c4 \uc911\ubcf5 \uc18c\ubaa8\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",B.f,"\u672a\u6536\u5230\u7ed3\u679c\u3002\u91cd\u8bd5\u540c\u4e00\u8bf7\u6c42\u4e0d\u4f1a\u91cd\u590d\u6263\u9664\u3002",B.j,"Ergebnis fehlt. Erneut versuchen \u2014 kein doppelter Verbrauch."],t.N)
B.abD=new A.n([B.G,"On success, a different compatible skill permanently replaces the old one. Rarity chances:",B.l,"Se riesce, una diversa abilit\xe0 compatibile sostituisce definitivamente la precedente. Probabilit\xe0 rarit\xe0:",B.k,"Al tener \xe9xito, una habilidad compatible distinta sustituye permanentemente a la anterior. Probabilidades:",B.i,"\u6210\u529f\u3059\u308b\u3068\u5225\u306e\u5bfe\u5fdc\u30b9\u30ad\u30eb\u306b\u6c38\u4e45\u5909\u66f4\u3055\u308c\u307e\u3059\u3002\u30ec\u30a2\u5ea6\u78ba\u7387\uff1a",B.h,"\uc131\uacf5 \uc2dc \ub2e4\ub978 \ud638\ud658 \uc2a4\ud0ac\ub85c \uc601\uad6c \uad50\uccb4\ub429\ub2c8\ub2e4. \ub4f1\uae09 \ud655\ub960:",B.f,"\u6210\u529f\u540e\u5c06\u6c38\u4e45\u66ff\u6362\u4e3a\u53e6\u4e00\u79cd\u517c\u5bb9\u6280\u80fd\u3002\u7a00\u6709\u5ea6\u6982\u7387\uff1a",B.j,"Bei Erfolg ersetzt eine andere kompatible F\xe4higkeit die alte dauerhaft. Seltenheitschancen:"],t.N)
