B.ack=new A.n([B.l,"Preparati al combattimento",B.k,"Prep\xe1rate para el combate",B.i,"\u6226\u95d8\u306b\u5099\u3048\u3088\u3046",B.h,"\uc804\ud22c\ub97c \uc900\ube44\ud558\uc138\uc694",B.f,"\u51c6\u5907\u6218\u6597",B.j,"Mach dich kampfbereit"],t.N)
