B.adQ=new A.n([B.l,"Accedi per scegliere il tuo nome definitivo.",B.k,"Inicia sesi\xf3n para elegir tu nombre definitivo.",B.i,"\u30ed\u30b0\u30a4\u30f3\u3057\u3066\u540d\u524d\u3092\u4e00\u5ea6\u3060\u3051\u8a2d\u5b9a\u3057\u3066\u304f\u3060\u3055\u3044\u3002",B.h,"\ub85c\uadf8\uc778\ud558\uc5ec \uc601\uad6c \uc774\ub984\uc744 \uc120\ud0dd\ud558\uc138\uc694.",B.f,"\u767b\u5f55\u4ee5\u9009\u62e9\u6c38\u4e45\u540d\u79f0\u3002",B.j,"Anmelden, um den dauerhaften Namen zu w\xe4hlen."],t.N)
